package studio.cardia.core

object LiverContent {
    private val segments = listOf("s1", "s2", "s3", "s4a", "s4b", "quadrate", "s5", "s6", "s7", "s8")
    private val impression = "A shallow impression on the visceral (inferior) surface, moulded in life by a neighbouring organ."

    val organ = Organ(
        id = "liver", name = "Liver", system = "Digestive", tagline = "Eight segments, each with its own supply.",
        assets = listOf("liver.glb"),
        layers = listOf("Surface", "Couinaud segments"),
        note = "Surface features, ligaments and Couinaud segments of the HRA liver. Hepatic vessels and bile ducts are not included. Segment colours are teaching colours.",
        structures = listOf(
            Structure("capsule", "Liver capsule", "Glisson's capsule", "A thin fibrous capsule, mostly covered by visceral peritoneum, enclosing the liver. At the porta hepatis it continues inward around the vessels and ducts.", "The liver parenchyma itself has few pain fibres; stretching of the capsule causes right upper quadrant pain.", listOf("VH_M_liver_capsule")),
            Structure("diaphragmatic", "Diaphragmatic surface", "Smooth dome", "The smooth, convex anterior, superior and posterior surface lying against the underside of the diaphragm.", "It is separated from the diaphragm by the subphrenic spaces, where abscesses can collect.", listOf("VH_M_diaphragmatic_surface"), tint = 0x8C3A31, decal = true),
            Structure("bare", "Bare area", "No peritoneum", "An area on the posterior diaphragmatic surface not covered by peritoneum, bounded by the coronary ligament. Here the liver lies directly against the diaphragm.", "It is a route by which infection or tumour can spread between abdomen and thorax.", listOf("VH_M_bare_area_of_liver"), tint = 0xA06A50, decal = true),
            Structure("impressions", "Visceral impressions", "Imprints of neighbours", "$impression This model marks gastric, duodenal, colic, renal, suprarenal and oesophageal impressions.", "The renal impression of the right kidney shows how closely the liver and kidney lie — the hepatorenal pouch (Morison's pouch) lies between them.", listOf("VH_M_gastric_impression_of_liver", "VH_M_duodenal_impression_of_liver", "VH_M_colic_impression_of_liver", "VH_M_renal_impression_of_liver", "VH_M_suprarenal_impression_of_liver", "VH_M_esophageal_impression_of_liver"), tint = 0xB06452, decal = true),
            Structure("porta", "Porta hepatis", "The liver's doorway", "A transverse fissure on the visceral surface where the portal vein and hepatic artery proper enter and the hepatic ducts leave, with nerves and lymphatics.", "Unlike most organs, the liver receives about three quarters of its blood from the portal vein and only a quarter from the hepatic artery.", listOf("VH_M_porta_hepatis"), tint = 0xD9B57C, decal = true),
            Structure("falciform", "Falciform ligament", "Anterior peritoneal fold", "A sickle-shaped fold of peritoneum attaching the liver to the anterior abdominal wall and diaphragm. It marks the external boundary between the left lateral segments (II, III) and segment IV.", "Its free edge contains the round ligament.", listOf("VH_M_falciform_ligament")),
            Structure("round", "Round ligament", "Ligamentum teres", "The fibrous remnant of the fetal left umbilical vein, running in the free edge of the falciform ligament to the visceral surface.", "In portal hypertension the para-umbilical veins alongside it can open and produce caput medusae.", listOf("VH_M_round_ligament_of_liver")),
            Structure("venosum", "Ligamentum venosum", "Ductus venosus remnant", "The fibrous remnant of the fetal ductus venosus, which shunted placental blood from the umbilical vein to the inferior vena cava, bypassing the liver.", "Its fissure separates the caudate lobe from the left lateral segments.", listOf("VH_M_ligamentum_venosum")),
            Structure("coronary", "Coronary & triangular ligaments", "Posterior attachments", "Peritoneal reflections from the liver to the diaphragm that bound the bare area; laterally they meet as the left and right triangular ligaments.", "Division of these ligaments is needed to mobilise the liver during surgery.", listOf("VH_M_coronary_ligament_of_liver", "VH_M_triangular_ligament_of_liver")),
            Structure("hepatoduodenal", "Hepatoduodenal ligament", "Carries the portal triad", "The right free edge of the lesser omentum, running from the porta hepatis to the duodenum. It encloses the portal vein, hepatic artery proper and common bile duct.", "Compressing it (the Pringle manoeuvre) temporarily controls inflow to the liver during surgery.", listOf("VH_M_hepataduodenal_ligament")),
            Structure("s1", "Segment I · Caudate lobe", "Independent drainage", "The caudate lobe lies posteriorly, between the inferior vena cava and the fissure for the ligamentum venosum. It receives branches from both right and left portal pedicles.", "It drains by small veins directly into the inferior vena cava, so it is often spared and enlarges in Budd–Chiari syndrome.", listOf("VH_M_caudate_lobe_of_liver"), depth = 1, tint = 0xD2A62C),
            Structure("s2", "Segment II", "Left lateral, superior", "The superior (posterior) part of the left lateral section, to the left of the falciform ligament.", "Segments II and III together form the left lateral section, commonly used in living-donor transplantation for children.", listOf("VH_M_left_posterolateral_segment"), depth = 1, tint = 0x7EA8DA),
            Structure("s3", "Segment III", "Left lateral, inferior", "The inferior (anterior) part of the left lateral section, to the left of the falciform ligament.", "Segment III is part of the anatomical left lobe along with segment II.", listOf("VH_M_left_anterolateral_segment"), depth = 1, tint = 0x5A8BD4),
            Structure("s4a", "Segment IVa", "Left medial, superior", "The superior part of segment IV, between the middle hepatic vein and the falciform ligament.", "Segment IV belongs to the functional left liver even though it lies to the right of the falciform ligament.", listOf("VH_M_left_superiomedial_segment"), depth = 1, tint = 0x9B7FD2),
            Structure("s4b", "Segment IVb", "Left medial, inferior", "The inferior part of segment IV, next to the gallbladder fossa. The quadrate lobe lies here on the visceral surface.", "Cantlie's line, from the gallbladder fossa to the inferior vena cava, separates segment IV from segments V and VIII.", listOf("VH_M_left_inferomedial_segment"), depth = 1, tint = 0xB79DE2),
            Structure("quadrate", "Quadrate lobe", "Anatomical lobe", "An anatomical lobe on the visceral surface bounded by the gallbladder fossa, the round ligament fissure and the porta hepatis. Functionally it belongs to segment IVb.", "Anatomical lobes (defined by surface landmarks) and functional segments (defined by vessels) do not coincide.", listOf("VH_M_quadrate_lobe_of_liver"), depth = 1, tint = 0xCBB8EC),
            Structure("s5", "Segment V", "Right anterior, inferior", "The inferior part of the right anterior section, next to the gallbladder fossa.", "Segments V and VIII (anterior) are separated from VI and VII (posterior) by the right hepatic vein.", listOf("VH_M_right_anteroinferior_segment"), depth = 1, tint = 0xE27B5F),
            Structure("s6", "Segment VI", "Right posterior, inferior", "The inferior part of the right posterior section, lying over the right kidney.", "Liver biopsies are commonly taken through the right lateral chest wall into the right lobe.", listOf("VH_M_right_posteroinferior_segment"), depth = 1, tint = 0xD95C7A),
            Structure("s7", "Segment VII", "Right posterior, superior", "The superior part of the right posterior section, high under the diaphragm.", "Superior segments sit above the plane of the portal bifurcation; inferior segments below it.", listOf("VH_M_right_posterosuperior_segment"), depth = 1, tint = 0xC0426A),
            Structure("s8", "Segment VIII", "Right anterior, superior", "The superior part of the right anterior section, beneath the dome of the diaphragm.", "Numbering runs clockwise from segment I when the liver is viewed from the front.", listOf("VH_M_right_anterosuperior_segment"), depth = 1, tint = 0xE99E70)
        ),
        lessons = listOf(
            Lesson("surfaces", "Surfaces and ligaments", "Reading the outside of the liver", 5, listOf(
                LessonStep("The largest gland", "The liver fills the right upper abdomen under the ribs and diaphragm. Its smooth diaphragmatic surface faces up and forward.", "Anterior view: the patient's right is on your left.", StudyView(listOf("diaphragmatic"), frame = emptyList())),
                LessonStep("The bare area", "Posteriorly, a region is not covered by peritoneum. Here the liver touches the diaphragm directly, bounded by the coronary ligament.", "Turned to the posterior view.", StudyView(listOf("bare", "coronary"), frame = emptyList(), yaw = 180f)),
                LessonStep("Fetal remnants", "The falciform ligament attaches the liver to the anterior abdominal wall. In its edge runs the round ligament (old umbilical vein); the ligamentum venosum is the old ductus venosus.", "Two fetal shunts, closed after birth, leave these fibrous cords.", StudyView(listOf("falciform", "round", "venosum"), frame = emptyList())),
                LessonStep("The visceral surface", "Seen from below, the liver carries impressions of the stomach, duodenum, colon, right kidney and adrenal gland, and the porta hepatis where vessels enter.", "Viewed from below and behind.", StudyView(listOf("impressions", "porta", "hepatoduodenal"), frame = emptyList(), pitch = -60f))
            )),
            Lesson("segments", "Couinaud's eight segments", "The functional anatomy surgeons use", 6, listOf(
                LessonStep("Why segments?", "Each Couinaud segment has its own branch of the portal vein, hepatic artery and bile duct, and is drained by hepatic veins running between segments. So a segment can be removed without starving its neighbours.", "Surface peeled away. Colours are teaching colours.", StudyView(segments, frame = emptyList(), peel = 1)),
                LessonStep("Right liver: V to VIII", "The right hepatic vein divides the right liver into an anterior section (V, VIII) and a posterior section (VI, VII). Inferior segments (V, VI) lie below the portal bifurcation, superior (VII, VIII) above.", "Find segment VI over the kidney and VIII under the dome.", StudyView(listOf("s5", "s6", "s7", "s8"), frame = emptyList(), peel = 1)),
                LessonStep("Left liver: II, III and IV", "Segment IV lies between Cantlie's line and the falciform ligament, divided into IVa (superior) and IVb (inferior). Segments II and III form the left lateral section.", "The quadrate lobe sits within IVb on the visceral surface.", StudyView(listOf("s2", "s3", "s4a", "s4b", "quadrate"), frame = emptyList(), peel = 1)),
                LessonStep("Segment I: the caudate lobe", "The caudate lobe lies posteriorly against the inferior vena cava and drains straight into it through its own short veins.", "Posterior view. This independent drainage explains why the caudate can enlarge when the main hepatic veins are blocked.", StudyView(listOf("s1"), frame = emptyList(), peel = 1, yaw = 180f)),
                LessonStep("Pull it apart", "Separating the segments shows how the liver is built from independent units. Numbering runs clockwise from I, viewed from the front.", "Rotate to see how they interlock.", StudyView(segments, frame = emptyList(), peel = 1, explode = .35f))
            ))
        ),
        questions = listOf(
            Question("What defines a Couinaud segment?", listOf("Surface fissures", "Its own portal pedicle and biliary drainage", "Peritoneal folds", "Lymph node groups"), 1, "Each segment has its own portal vein, hepatic artery and bile duct branch, with hepatic veins between segments."),
            Question("Which segment drains directly into the inferior vena cava?", listOf("Segment I (caudate)", "Segment IV", "Segment VI", "Segment III"), 0, "The caudate lobe drains by short veins directly into the IVC."),
            Question("The round ligament of the liver is the remnant of the…", listOf("Ductus venosus", "Left umbilical vein", "Ductus arteriosus", "Umbilical artery"), 1, "Ligamentum teres hepatis is the obliterated left umbilical vein; the ductus venosus becomes the ligamentum venosum."),
            Question("Which line separates the functional right and left liver?", listOf("Falciform ligament", "Cantlie's line", "Round ligament", "Coronary ligament"), 1, "Cantlie's line runs from the gallbladder fossa to the IVC, along the middle hepatic vein."),
            Question("Where is the liver not covered by peritoneum?", listOf("Porta hepatis only", "Bare area", "Quadrate lobe", "Falciform ligament"), 1, "The bare area lies directly against the diaphragm, bounded by the coronary ligament."),
            Question("Most of the liver's blood supply comes from the…", listOf("Hepatic artery proper", "Portal vein", "Hepatic veins", "Inferior vena cava"), 1, "About 75% of hepatic inflow is portal venous blood; about 25% is arterial.")
        ),
        references = listOf(
            "OpenStax · Accessory organs in digestion" to "https://openstax.org/books/anatomy-and-physiology-2e/pages/23-6-accessory-organs-in-digestion-the-liver-pancreas-and-gallbladder",
            "NIDDK · Your digestive system" to "https://www.niddk.nih.gov/health-information/digestive-diseases/digestive-system-how-it-works"
        ),
        yaw = 0f, pitch = 4f
    )
}
